$supportConversations = $data['conversations'] ?? [];
?>
<style>
.support-admin{display:grid;grid-template-columns:320px minmax(0,1fr);grid-template-rows:minmax(0,1fr);height:min(720px,calc(100vh - 190px));min-height:500px;overflow:hidden;border:1px solid #2a3037;border-radius:18px;background:#151a1f;color:#e8ebee;box-shadow:0 18px 45px rgba(0,0,0,.2)}
.support-inbox{display:flex;min-width:0;min-height:0;flex-direction:column;border-right:1px solid #2a3037;background:#11161a}.support-inbox-head{padding:20px;border-bottom:1px solid #2a3037}.support-inbox-head h2{margin:0;color:#f0cf56;font-size:21px}.support-inbox-head p{margin:5px 0 0;color:#98a4af;font-size:13px}.support-inbox-list{flex:1;min-height:0;overflow:auto}.support-thread{display:block;width:100%;padding:15px 17px;border:0;border-bottom:1px solid #252b31;background:transparent;color:inherit;text-align:left;cursor:pointer}.support-thread:hover,.support-thread.is-active{background:#20262d}.support-thread.is-active{box-shadow:inset 3px 0 #dfb936}.support-thread-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.support-thread-name{overflow:hidden;color:#f2f4f5;font-weight:700;text-overflow:ellipsis;white-space:nowrap}.support-thread-time{flex:0 0 auto;color:#8c98a4;font-size:10px}.support-thread-preview{display:block;overflow:hidden;margin-top:5px;color:#9da8b2;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.support-thread-badge{display:inline-grid;min-width:20px;height:20px;margin-left:8px;padding:0 5px;place-items:center;border-radius:999px;background:#d2af31;color:#15181b;font-size:11px;font-weight:800}.support-thread-state{display:block;margin-top:7px;color:#d6b83f;font-size:10px;text-transform:uppercase}.support-admin-chat{display:flex;min-width:0;min-height:0;height:100%;flex-direction:column}.support-admin-chat-head{display:flex;flex:0 0 auto;align-items:center;justify-content:space-between;gap:15px;padding:17px 20px;border-bottom:1px solid #2a3037}.support-admin-chat-head strong{color:#f2f4f5;font-size:17px}.support-admin-chat-head small{display:block;margin-top:4px;color:#98a4af}.support-admin-log{flex:1;min-height:0;overflow:auto;padding:20px;background:#151a1f}.support-admin-msg{max-width:min(74%,580px);margin:0 0 14px;padding:10px 13px;border:1px solid #303740;border-radius:13px;background:#20262d;color:#e7eaed;white-space:pre-wrap;overflow-wrap:anywhere}.support-admin-msg.is-admin{margin-left:auto;border-color:#8e741d;background:#534619;color:#fff}.support-admin-meta{display:block;margin-top:6px;color:#aeb8c2;font-size:10px}.support-admin-compose{display:flex;flex:0 0 auto;gap:9px;padding:14px;border-top:1px solid #2a3037}.support-admin-compose input{min-width:0;flex:1;border:1px solid #39434c;border-radius:10px;padding:11px 13px;background:#0f1418;color:#f4f6f8;font:inherit}.support-admin-compose input::placeholder{color:#8a96a1}.support-admin-compose button{border:0;border-radius:10px;padding:0 18px;background:#d1ad31;color:#171a1c;font-weight:800;cursor:pointer}.support-admin-compose button:disabled{opacity:.5;cursor:not-allowed}.support-admin-empty{display:grid;flex:1;place-items:center;padding:25px;color:#909ba5;text-align:center}.support-admin-alert{min-height:22px;padding:0 18px 8px;color:#ff9a9e}
/* Keep the reply controls in a dedicated row so a long message history cannot push them out of view. */
.support-admin-chat{display:grid;grid-template-rows:auto minmax(0,1fr) auto auto;overflow:hidden}
.support-admin-chat-head{height:auto;min-height:0;box-sizing:border-box}
.support-admin-log{min-height:0}
.support-admin-alert{min-height:0;box-sizing:border-box}
.support-admin-compose{position:relative;z-index:1;min-width:0;box-sizing:border-box;background:#151a1f}
@media(max-width:760px){.support-admin{grid-template-columns:220px minmax(0,1fr);height:calc(100vh - 160px);min-height:440px}.support-inbox-head{padding:15px}.support-admin-chat-head{padding:14px}.support-admin-log{padding:13px}.support-admin-msg{max-width:90%}}
@media(max-width:540px){.support-admin{grid-template-columns:1fr;grid-template-rows:190px minmax(0,1fr);height:calc(100vh - 145px)}.support-inbox{border-right:0;border-bottom:1px solid #2a3037}.support-inbox-head{padding:10px 14px}.support-inbox-head h2{font-size:17px}.support-thread{padding:9px 13px}.support-thread-state{display:none}.support-admin-chat-head strong{font-size:14px}}
</style>
<section class="support-admin">
    <aside class="support-inbox">
        <div class="support-inbox-head"><h2><i class="fas fa-comments"></i> Chat hỗ trợ</h2><p>Hội thoại với khách hàng DailyMart</p></div>
        <div id="support-inbox-list" class="support-inbox-list"></div>
    </aside>
    <section class="support-admin-chat">
        <header class="support-admin-chat-head"><div><strong id="support-admin-customer">Chọn một cuộc trò chuyện</strong><small id="support-admin-status">Tin nhắn mới sẽ xuất hiện theo thời gian thực.</small></div></header>
        <div id="support-admin-log" class="support-admin-log"><div class="support-admin-empty">Chọn cuộc trò chuyện ở danh sách để xem tin nhắn và phản hồi.</div></div>
        <div id="support-admin-alert" class="support-admin-alert" aria-live="polite"></div>
        <form id="support-admin-form" class="support-admin-compose"><input id="support-admin-input" maxlength="2000" autocomplete="off" placeholder="Chọn cuộc trò chuyện trước khi trả lời..." disabled><button type="submit" disabled>Gửi</button></form>
    </section>
</section>
<script src="/socket.io/socket.io.js"></script>
<script>
(function(){
    const initial=<?php echo json_encode($supportConversations, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE); ?>;
    const list=document.getElementById('support-inbox-list'),log=document.getElementById('support-admin-log'),customerName=document.getElementById('support-admin-customer'),status=document.getElementById('support-admin-status'),alertBox=document.getElementById('support-admin-alert');
    const form=document.getElementById('support-admin-form'),input=document.getElementById('support-admin-input'),send=form.querySelector('button');
    const tokenUrl='/Baitaplon/SupportChat/Token',historyUrl=id=>'/Baitaplon/SupportChat/History/'+encodeURIComponent(id);
    let conversations=Array.isArray(initial)?initial:[],selectedId=null,socket=null,shown=new Set(),busy=false,renewTimer=null,tokenExpiresAt=0;
    function setAlert(message){alertBox.textContent=message||'';}
    function formatTime(value){if(!value)return '';const raw=String(value);const date=new Date(raw.includes('T')?raw:raw.replace(' ','T')+'Z');return isNaN(date.getTime())?'':date.toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'});}
    function renderInbox(){list.replaceChildren();if(!conversations.length){const empty=document.createElement('div');empty.className='support-admin-empty';empty.textContent='Chưa có cuộc trò chuyện nào.';list.appendChild(empty);return;}conversations.forEach(conversation=>{const button=document.createElement('button');button.type='button';button.className='support-thread'+(Number(conversation.id)===Number(selectedId)?' is-active':'');button.dataset.id=conversation.id;const top=document.createElement('span');top.className='support-thread-top';const name=document.createElement('span');name.className='support-thread-name';name.textContent=conversation.customer_name||'Khách hàng';const time=document.createElement('span');time.className='support-thread-time';time.textContent=formatTime(conversation.updated_at);top.append(name,time);if(Number(conversation.unread_count)>0){const badge=document.createElement('span');badge.className='support-thread-badge';badge.textContent=conversation.unread_count;top.appendChild(badge);}const preview=document.createElement('span');preview.className='support-thread-preview';preview.textContent=(conversation.last_sender_type==='admin'?'Bạn: ':'')+(conversation.last_message||'Chưa có tin nhắn');const state=document.createElement('span');state.className='support-thread-state';state.textContent=conversation.status==='closed'?'Đã đóng':'Đang mở';button.append(top,preview,state);button.addEventListener('click',()=>selectConversation(conversation.id));list.appendChild(button);});}
    function addMessage(message){const id=String(message.id);if(shown.has(id))return;shown.add(id);const item=document.createElement('div');item.className='support-admin-msg'+(message.senderType==='admin'||message.sender_type==='admin'?' is-admin':'');item.dataset.messageId=id;item.textContent=String(message.body||'');const meta=document.createElement('small');meta.className='support-admin-meta';meta.textContent=(message.senderName||message.sender_name||'')+' · '+formatTime(message.createdAt||message.created_at);item.appendChild(meta);log.appendChild(item);log.scrollTop=log.scrollHeight;}
    function updateSelectedStatus(state){const closed=state==='closed';status.textContent=closed?'Hội thoại đã đóng':(socket&&socket.connected?'Đang trực tuyến':'Đang kết nối…');input.disabled=closed;send.disabled=closed||!socket||!socket.connected||!selectedId;}
    async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Không thể tải dữ liệu chat.');return result;}
    async function connect(){if(!window.io)throw new Error('Không tải được dịch vụ WebSocket.');socket=window.io({path:'/socket.io/',transports:['websocket','polling'],auth:async callback=>{try{const result=await api(tokenUrl);tokenExpiresAt=Number(result.expiresAt)*1000;callback({token:result.token});}catch(error){callback({token:''});setAlert(error.message);}},reconnection:true});socket.on('connect',()=>{clearTimeout(renewTimer);renewTimer=setTimeout(()=>{if(socket&&socket.connected){socket.disconnect();socket.connect();}},Math.max(1000,tokenExpiresAt-Date.now()-60000));if(selectedId)joinSelected();else status.textContent='Đã kết nối · chờ chọn hội thoại';renderInbox();});socket.on('disconnect',()=>{clearTimeout(renewTimer);status.textContent='Mất kết nối · đang thử lại';send.disabled=true;});socket.on('connect_error',error=>setAlert(error.message||'Không thể kết nối chat.'));socket.on('support:message',message=>{if(Number(message.conversationId)===Number(selectedId)){addMessage(message);if(message.senderType==='customer'&&socket.connected)socket.emit('support:read',selectedId);}const row=conversations.find(item=>Number(item.id)===Number(message.conversationId));if(row){row.last_message=message.body;row.last_sender_type=message.senderType;row.updated_at=message.createdAt;if(message.senderType==='customer'&&Number(selectedId)!==Number(message.conversationId))row.unread_count=Number(row.unread_count||0)+1;else if(Number(selectedId)===Number(message.conversationId)||message.senderType==='admin')row.unread_count=0;conversations.sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));}else{conversations.unshift({id:message.conversationId,customer_name:message.senderType==='customer'?message.senderName:'Khách hàng',status:'open',last_message:message.body,last_sender_type:message.senderType,updated_at:message.createdAt,unread_count:message.senderType==='customer'&&Number(selectedId)!==Number(message.conversationId)?1:0});}renderInbox();});socket.on('support:inbox-update',event=>{const row=conversations.find(item=>Number(item.id)===Number(event.conversationId));if(row&&event.status)row.status=event.status;renderInbox();});socket.on('support:status',event=>{if(Number(event.conversationId)===Number(selectedId)){updateSelectedStatus(event.status);const row=conversations.find(item=>Number(item.id)===Number(selectedId));if(row)row.status=event.status;renderInbox();}});}
    function joinSelected(){if(!socket||!socket.connected||!selectedId)return;socket.emit('support:join',selectedId,async result=>{if(!result||!result.ok){setAlert(result&&result.error||'Không mở được hội thoại.');return;}updateSelectedStatus(result.status);try{const data=await api(historyUrl(selectedId));shown.clear();log.replaceChildren();data.messages.forEach(addMessage);updateSelectedStatus(data.conversation.status);const row=conversations.find(item=>Number(item.id)===Number(selectedId));if(row)row.unread_count=0;socket.emit('support:read',selectedId);renderInbox();window.dispatchEvent(new Event('support:unread-refresh'));}catch(error){setAlert(error.message);}});}
    async function selectConversation(id){selectedId=Number(id);shown.clear();log.replaceChildren();customerName.textContent='Đang tải…';input.disabled=true;send.disabled=true;renderInbox();setAlert('');try{if(!socket)await connect();const row=conversations.find(item=>Number(item.id)===selectedId);customerName.textContent=row?row.customer_name:'Khách hàng';if(socket.connected)joinSelected();}catch(error){setAlert(error.message);}}
    form.addEventListener('submit',event=>{event.preventDefault();const message=input.value.trim();if(!message||!socket||!socket.connected||!selectedId||busy)return;busy=true;send.disabled=true;socket.emit('support:send',{conversationId:selectedId,message},result=>{busy=false;if(!result||!result.ok){setAlert(result&&result.error||'Không gửi được tin nhắn.');updateSelectedStatus('open');}else{input.value='';setAlert('');updateSelectedStatus('open');}});});
    renderInbox();connect().catch(error=>{setAlert(error.message);status.textContent='Không kết nối được';});
})();
</script>
